  {
    "question": "Let A = {1,2,3,4}. Define a relation R on A by a R b ⇔ a + b is even. Which of the following correctly describes the properties of R?",
    "options": {
      "A": "Reflexive only",
      "B": "Symmetric and transitive only",
      "C": "Reflexive, symmetric, and transitive",
      "D": "None of the above"
    },
    "correct_answer": "C",
    "explanation": "For any a, a + a = 2a is even ⇒ reflexive. If a + b is even then b + a is even ⇒ symmetric. If a + b and b + c are even, adding gives a + c even ⇒ transitive. Hence R is an equivalence relation.",
    "difficulty": "Medium"
  },
  {
    "question": "How many injective (one‑to‑one) functions exist from a set X with 6 elements to a set Y with 9 elements?",
    "options": {
      "A": "9P6 (9 × 8 × 7 × 6 × 5 × 4)",
      "B": "6⁹",
      "C": "9⁶",
      "D": "6!"
    },
    "correct_answer": "A",
    "explanation": "An injective function chooses a distinct image in Y for each of the 6 elements of X. The number of ways is the permutation 9P6 = 9·8·7·6·5·4 = 60 480.",
    "difficulty": "Medium"
  },
  {
    "question": "If f : A→B is surjective and g : B→C is injective, which statement about the composition g∘f is always true?",
    "options": {
      "A": "g∘f is injective",
      "B": "g∘f is surjective",
      "C": "g∘f is both injective and surjective",
      "D": "Neither injectivity nor surjectivity is guaranteed"
    },
    "correct_answer": "D",
    "explanation": "Surjectivity of f does not make g∘f surjective because g may miss elements of C. Injectivity of g does not make g∘f injective because f may map distinct elements of A to the same element of B. Hence no property is guaranteed.",
    "difficulty": "Medium"
  },
  {
    "question": "A set S contains 4 distinct elements. How many subsets of S have exactly 2 elements?",
    "options": {
      "A": "4",
      "B": "6",
      "C": "8",
      "D": "12"
    },
    "correct_answer": "B",
    "explanation": "Choosing 2 elements from 4 is a combination: C(4,2) = 4!/(2!·2!) = 6.",
    "difficulty": "Medium"
  },
  {
    "question": "Let |A| = 5 and |B| = 3. How many onto (surjective) functions f : A→B exist?",
    "options": {
      "A": "3⁵",
      "B": "3! × S(5,3) where S(5,3)=25",
      "C": "5! / (5‑3)!",
      "D": "0"
    },
    "correct_answer": "B",
    "explanation": "The number of onto functions from an m‑element set to an n‑element set is n!·S(m,n). Here S(5,3)=25, so 3!·25 = 6·25 = 150.",
    "difficulty": "Medium"
  }
]
